import{a as e}from"./api-CJXuuMJ9.js";const o={async getAllArtworks(){return(await e.get("/artworks")).data},async getArtworkById(r){return(await e.get(`/artworks/${r}`)).data},async searchArtworks(r){return(await e.get(`/artworks/search/${encodeURIComponent(r)}`)).data},async filterArtworksByTags(r){return(await e.get(`/artworks/filter/${r.join(",")}`)).data},async createArtwork(r){return(await e.post("/artworks",r)).data},async updateArtwork(r,t){return(await e.put(`/artworks/${r}`,t)).data},async deleteArtwork(r){await e.delete(`/artworks/${r}`)},async getRecommendedArtworks(r){return(await e.get(`/artworks/recommendations${r?`?count=${r}`:""}`)).data},async getSimilarArtworks(r,t){return(await e.get(`/artworks/${r}/similar${t?`?count=${t}`:""}`)).data},async getArtworkAnalytics(r){return(await e.get(`/artworks/${r}/analytics`)).data}};export{o as a};
